function roleName(role){return {customer:'Khách hàng',staff:'Nhân viên',manager:'Quản lý',admin:'Quản trị viên'}[role]||'Khách';}
function roleHome(role){return {staff:'#/nhan-vien',manager:'#/quan-ly',admin:'#/quan-tri'}[role]||'#/tai-khoan';}
const main = document.querySelector('#main');
const money = n => new Intl.NumberFormat('vi-VN', {style:'currency',currency:'VND'}).format(n);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();
function read(key,fallback) { try { return JSON.parse(localStorage.getItem('libra.'+key)) ?? fallback; } catch { return fallback; } }
function save(key,value) { try { localStorage.setItem('libra.'+key,JSON.stringify(value)); } catch { toast('Trình duyệt không thể lưu dữ liệu. Vui lòng kiểm tra dung lượng lưu trữ.'); } }
let loaded = false;
let books = [], cart = read('cart',[]), favorites = read('favorites',[]), user = read('user',null), coupon = '', routeVersion = 0;
if (!Array.isArray(cart)) cart = [];
if (!Array.isArray(favorites)) favorites = [];
const categories = ['Văn học','Kỹ năng sống','Kinh tế','Tâm lý','Thiếu nhi','Khoa học'];
let toastTimer;
function toast(text) { const el=document.querySelector('#toast'); el.textContent=text; el.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('show'),3200); }
function header() { const adminLink=document.querySelector('#admin-link');if(adminLink){adminLink.hidden=!['admin','manager','staff'].includes(user?.role);adminLink.href=roleHome(user?.role);adminLink.textContent=roleName(user?.role);} document.querySelector('#cart-count').textContent=cart.reduce((n,i)=>n+i.quantity,0); document.querySelector('#account-link').textContent=user?.name || 'Tài khoản'; document.querySelector('#demo-label').hidden=!LIBRA_CONFIG.useMock; }
function cover(book,extra='') { if(!LIBRA_CONFIG.useMock&&book.imageUrl){const url=safeLiveUrl(book.imageUrl);if(url)return `<div class="book-cover real-cover ${extra}"><img src="${esc(url)}" alt="${esc(book.title)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></div>`;}  const colors=['#b56a36','#345d56','#c5a578','#71865b','#324e63','#739bb0','#a06466','#873f36','#657b88','#6c7945','#954e3e','#343c66']; const color=colors.includes(book.color)?book.color:'#345d56'; return `<div class="book-cover ${extra} pattern-${Number(book.id)%4}" style="--cover:${color}"><span class="cover-author">${esc(book.author)}</span><strong>${esc(book.title)}</strong><span class="cover-art" aria-hidden="true"><i></i><i></i><i></i></span><span class="cover-foot">LIBRA • TUYỂN CHỌN</span></div>`; }
function card(book) { const liked=favorites.includes(book.id); return `<article class="book-card"><div class="book-stage"><a href="#/sach/${book.id}" aria-label="Xem ${esc(book.title)}">${cover(book)}</a>${book.originalPrice>book.price?`<span class="discount">−${Math.round((1-book.price/book.originalPrice)*100)}%</span>`:''}<button class="favorite ${liked?'liked':''}" data-favorite="${book.id}" aria-label="${liked?'Bỏ yêu thích':'Yêu thích'} ${esc(book.title)}" aria-pressed="${liked}">${liked?'♥':'♡'}</button></div><div class="book-info"><span class="category-label">${esc(book.category)}</span><h3><a href="#/sach/${book.id}">${esc(book.title)}</a></h3><p>${esc(book.author)}</p>${book.rating?`<div class="rating">★ <span>${book.rating} <span class="muted">/ 5</span></span></div>`:''}<div class="price-row"><div><b>${money(book.price)}</b> ${book.originalPrice>book.price?`<del>${money(book.originalPrice)}</del>`:''}</div><button class="add" data-add="${book.id}" ${book.stock===0?'disabled':''} aria-label="Thêm ${esc(book.title)} vào giỏ">${book.stock===0?'Hết hàng':'Thêm vào giỏ'}</button></div></div></article>`; }
function empty(title,text,link='#/sach',label='Khám phá sách') { return `<div class="empty"><span aria-hidden="true">♧</span><h2>${title}</h2><p>${text}</p><a class="button" href="${link}">${label} →</a></div>`; }
function heading(title,description='') { return `<div class="page-heading"><div class="eyebrow">LIBRA / NHÀ SÁCH CỦA BẠN</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`; }
function home() {
 const newest=[...books].sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0)||b.id-a.id).slice(0,4);
 const genres=[...new Set([...books.map(b=>b.category),...categories])].slice(0,6);
 const artBooks=[{id:1,title:'Một trang sách, một thế giới',author:'GÓC ĐỌC LIBRA',color:'#b56a36'},{id:2,title:'Nuôi dưỡng sự tò mò',author:'READ • DREAM • DISCOVER',color:'#324e63'},{id:3,title:'Chậm lại để đọc',author:'DÀNH THỜI GIAN CHO BẠN',color:'#c5a578'}];
 return `<div class="home-refresh"><section class="wrap home-intro"><div><span class="home-pill">● KHÔNG GIAN DÀNH CHO NGƯỜI YÊU SÁCH</span><h1>Mở trang sách.<br><em>Mở thêm</em> thế giới.</h1><p>Khám phá những câu chuyện, tìm kiếm tri thức và chọn cuốn sách tiếp theo của bạn tại Libra.</p><div class="home-actions"><a class="button" href="#/sach">Khám phá sách ↗</a><button class="button secondary" data-home-categories>Xem danh mục</button></div><div class="home-facts"><div><b>${books.length}</b><span>Tựa sách</span></div><div><b>${new Set(books.map(b=>b.category)).size}</b><span>Thể loại</span></div><div><b>Mỗi ngày</b><span>Một trang mới</span></div></div></div><div class="home-art"><div class="home-art-books">${(books.length>=3?books.slice(0,3):artBooks).map(b=>cover(b)).join('')}</div><blockquote><span>“</span><p>Một cuốn sách hay là một cánh cửa đang chờ mở.</p><footer>Libra / Góc cảm hứng</footer></blockquote></div></section>
 <div class="wrap home-service-strip"><span>📦 <b>Giao sách tận nơi</b></span><span>♡ <b>Lưu sách yêu thích</b></span><span>🔖 <b>Thanh toán khi nhận hàng</b></span><a href="#/chinh-sach">Chính sách mua hàng ↗</a></div><section class="home-tint" id="home-categories"><div class="wrap section"><div class="section-title"><div><div class="eyebrow">TÌM ĐIỀU BẠN YÊU THÍCH</div><h2>Khám phá theo thể loại</h2></div><a class="text-link" href="#/sach">Xem tất cả →</a></div><div class="home-genres">${genres.map((c,i)=>`<a href="#/sach?category=${encodeURIComponent(c)}"><span aria-hidden="true">${['📖','💼','☀️','🔭','🎈','🌍'][i%6]}</span><b>${esc(c)}</b><small>${books.filter(b=>b.category===c).length} tựa sách</small></a>`).join('')}</div></div></section>
 <section class="wrap section home-new"><div class="section-title"><div><div class="eyebrow">MỚI TRÊN KỆ</div><h2>Sách mới, cảm hứng mới</h2></div><a class="text-link" href="#/sach">Xem tất cả →</a></div>${newest.length?`<div class="book-grid">${newest.map(card).join('')}</div>`:'<div class="home-empty"><span>📚</span><h3>Kệ sách đang chờ những câu chuyện mới</h3><p>Nhà sách đang cập nhật danh mục. Hẹn bạn ghé lại để tìm cuốn sách yêu thích.</p></div>'}</section>
 ${books.length>4?`<section class="wrap section home-new home-picks"><div class="section-title"><div><div class="eyebrow">MỘT CHÚT TÒ MÒ MỖI NGÀY</div><h2>Gợi ý cho kệ sách của bạn</h2></div><a class="text-link" href="#/sach">Khám phá thêm →</a></div><div class="book-grid">${books.filter(b=>!newest.some(n=>n.id===b.id)).slice(0,4).map(card).join('')}</div></section>`:''}<section class="home-tint"><div class="wrap section home-about"><div><div class="eyebrow">VỀ CHÚNG TÔI</div><h2>Giới thiệu Libra</h2><p>Libra là không gian dành cho những người yêu sách. Từ tìm kiếm, lưu cuốn sách yêu thích đến đặt hàng, chúng tôi giúp hành trình chọn sách của bạn trở nên đơn giản hơn.</p><div class="home-values">${[['📚','Chọn theo sở thích','Khám phá sách theo từng thể loại.'],['♡','Kệ sách của riêng bạn','Lưu lại những cuốn muốn đọc.'],['🚚','Giao đến tận tay','Theo dõi đơn hàng trong tài khoản.'],['🔖','Thông tin rõ ràng','Xem giá và tồn kho trước khi chọn.']].map(([icon,title,desc])=>`<div><span aria-hidden="true">${icon}</span><h3>${title}</h3><p>${desc}</p></div>`).join('')}</div></div><div class="home-library" aria-label="Minh họa kệ sách Libra"><div class="library-label">THE LIBRA LIBRARY<br><b>Một góc nhỏ.<br>Vạn điều hay.</b></div>${[0,1,2].map(row=>`<div class="library-shelf" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i style="--spine:${['#b96c45','#e6bf7b','#62798e','#f0deba','#304861'][(i+row)%5]};--height:${85+(i*17+row*11)%65}px">${['LIBRA','READ','STORIES'][i%3]}</i>`).join('')}</div>`).join('')}<span class="library-badge">Đọc một chút.<br><b>Khám phá nhiều hơn.</b></span></div></div></section>
 <section class="wrap section"><div class="home-banner"><div><div class="eyebrow">DÀNH CHO HÀNH TRÌNH ĐỌC</div><h2>Đọc nhiều hơn.<br>Khám phá nhiều hơn.</h2><p>${LIBRA_CONFIG.useMock?'Khám phá ưu đãi với mã LIBRA10.':'Nhập mã GIAM10 tại giỏ hàng để kiểm tra ưu đãi.'}</p></div><a class="button light" href="#/sach">Khám phá ngay →</a></div></section></div>`;
}
document.addEventListener('click',event=>{if(event.target.closest('[data-home-categories]'))document.querySelector('#home-categories')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});
function catalog(params, favoriteOnly=false) {
 const q=params.get('q')||'',category=params.get('category')||'',max=Number(params.get('max'))||0,sort=params.get('sort')||'featured',sale=params.get('sale')==='1',stock=params.get('stock')==='1';
 let list=books.filter(b=>(!favoriteOnly||favorites.includes(b.id))&&(!q||normalize(b.title+' '+b.author).includes(normalize(q)))&&(!category||b.category===category)&&(!max||b.price<=max)&&(!sale||b.originalPrice>b.price)&&(!stock||b.stock>0));
 if(sort==='price-asc')list.sort((a,b)=>a.price-b.price); if(sort==='price-desc')list.sort((a,b)=>b.price-a.price); if(sort==='popular')list.sort((a,b)=>b.rating-a.rating); if(sort==='newest')list.sort((a,b)=>b.id-a.id);
 const page=Math.max(1,Math.min(Number(params.get('page'))||1,Math.ceil(list.length/8)||1));
 return `<section class="wrap section">${heading(favoriteOnly?'Kệ sách yêu thích':q?`Kết quả cho “${esc(q)}”`:'Tìm cuốn sách dành cho bạn.','Một chút tò mò có thể đưa bạn đến một câu chuyện tuyệt vời.')}<div class="catalog-layout"><aside class="filters"><h3>Bộ lọc sách</h3><form id="filter-form"><label>Danh mục<select name="category"><option value="">Tất cả danh mục</option>${categories.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></label><label>Khoảng giá<select name="max"><option value="0">Tất cả mức giá</option>${[100000,150000,200000].map(n=>`<option value="${n}" ${max===n?'selected':''}>Đến ${money(n)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="stock" ${stock?'checked':''}> Chỉ sách còn hàng</label><label class="check"><input type="checkbox" name="sale" ${sale?'checked':''}> Sách đang giảm giá</label><button class="button" type="submit">Áp dụng bộ lọc</button><a class="clear-filter" href="${favoriteOnly?'#/yeu-thich':'#/sach'}">Xóa bộ lọc</a></form><div class="filter-note">Đọc điều bạn thích.<br><em>Khám phá điều bạn chưa biết.</em><span>✳</span></div></aside><div><div class="results-bar"><span><b>${list.length}</b> cuốn sách${sale?' đang ưu đãi':''}</span><label>Sắp xếp <select id="sort">${[['featured','Đề xuất'],['popular','Được yêu thích'],['newest','Mới nhất'],['price-asc','Giá tăng dần'],['price-desc','Giá giảm dần']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${list.length?`<div class="book-grid catalog-grid">${list.slice((page-1)*8,page*8).map(card).join('')}</div><div class="pagination">${Array.from({length:Math.ceil(list.length/8)},(_,i)=>`<button data-page="${i+1}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}</div>`:empty(favoriteOnly?'Kệ sách đang chờ bạn':'Chưa tìm thấy sách phù hợp',favoriteOnly?'Nhấn trái tim trên một cuốn sách để lưu vào đây.':'Thử một từ khóa khác hoặc xóa bộ lọc.')}</div></div></section>`;
}
function detail(id) {
 const b=books.find(b=>b.id===id); if(!b)return empty('Không tìm thấy cuốn sách','Cuốn sách này hiện không có trong danh mục.');
 return `<section class="wrap section"><div class="breadcrumb"><a href="#/">Trang chủ</a> / <a href="#/sach">Sách</a> / ${esc(b.title)}</div><div class="detail-layout"><div class="detail-cover">${cover(b)}<span>${b.imageUrl?'Ảnh bìa sách':'Bìa minh họa • Libra collection'}</span></div><div class="detail-copy"><div class="eyebrow">${esc(b.category)}</div><h1>${esc(b.title)}</h1><p class="muted">Tác giả: <b>${esc(b.author)}</b></p><p class="rating">★ ★ ★ ★ ★ <span>${b.rating}/5 · Đánh giá minh họa</span></p><div class="detail-price">${money(b.price)} ${b.originalPrice>b.price?`<del>${money(b.originalPrice)}</del>`:''}</div><p>${esc(b.description)}</p><p class="stock">${b.stock>0?`● Còn ${b.stock} cuốn`:'Hết hàng'}</p><div class="buy-row"><label>Số lượng <input id="quantity" type="number" min="1" max="${b.stock||1}" value="1" ${!b.stock?'disabled':''}></label><button class="button" data-add="${b.id}" data-detail="true" ${!b.stock?'disabled':''}>Thêm vào giỏ hàng +</button><button class="heart-button" data-favorite="${b.id}" aria-label="Yêu thích" aria-pressed="${favorites.includes(b.id)}">${favorites.includes(b.id)?'♥':'♡'}</button></div><div class="detail-perks">↗ Miễn phí giao hàng từ ${LIBRA_CONFIG.useMock?'299.000':'300.000'}₫<br>↻ Xem <a href="#/chinh-sach">chính sách giao hàng và đổi trả</a></div></div></div><div class="book-description"><div><h2>Về cuốn sách</h2><p>${esc(b.description)} Đây là gợi ý dành cho những bạn đọc yêu thích ${esc(b.category.toLowerCase())}. Hãy dành một khoảng thời gian nhỏ để lật mở từng trang và khám phá theo cách của riêng mình.</p></div><div><h2>Thông tin chi tiết</h2><dl><dt>Tác giả</dt><dd>${esc(b.author)}</dd><dt>Số trang</dt><dd>${b.pages}</dd><dt>Ngôn ngữ</dt><dd>${esc(b.language)}</dd><dt>Năm phát hành</dt><dd>${b.year}</dd><dt>Hình thức</dt><dd>Bìa mềm</dd></dl></div></div><div class="section-title"><h2>Có thể bạn cũng thích</h2><a href="#/sach">Khám phá thêm →</a></div><div class="book-grid">${books.filter(x=>x.id!==id).sort((a,c)=>Number(c.category===b.category)-Number(a.category===b.category)).slice(0,4).map(card).join('')}</div></section>`;
}
function cartItems() { return cart.map(i=>({...i,book:books.find(b=>b.id===i.bookId)})).filter(i=>i.book); }
function selectedItems() { return cartItems().filter(i=>i.selected!==false); }
function totals() { const subtotal=selectedItems().reduce((n,i)=>n+i.quantity*i.book.price,0); const discount=coupon==='LIBRA10'?Math.min(Math.round(subtotal*.1),50000):0; const shipping=subtotal===0||subtotal>=299000?0:25000; return {subtotal,discount,shipping,total:subtotal-discount+shipping}; }
function summary(checkout=false) { if(!LIBRA_CONFIG.useMock)return liveSummary(checkout); const t=totals(); return `<aside class="order-summary"><h2>Tóm tắt đơn hàng</h2><div><span>Tạm tính</span><b>${money(t.subtotal)}</b></div><div><span>Vận chuyển</span><b>${t.shipping?money(t.shipping):'Miễn phí'}</b></div>${t.discount?`<div class="green"><span>Giảm giá LIBRA10</span><b>−${money(t.discount)}</b></div>`:''}<div class="total"><span>Tổng cộng</span><b>${money(t.total)}</b></div>${!checkout?`<form id="coupon-form"><label for="coupon">Mã ưu đãi</label><div class="coupon-row"><input id="coupon" placeholder="Nhập LIBRA10" value="${esc(coupon)}"><button>Áp dụng</button></div></form>${selectedItems().length?`<a href="#/thanh-toan" class="button full">Thanh toán (${selectedItems().length} tựa sách) →</a>`:`<button class="button full" disabled>Chọn sách để thanh toán</button>`}`:''}<p class="hint">${t.subtotal<299000?`Mua thêm ${money(299000-t.subtotal)} để được miễn phí vận chuyển.`:'Đơn hàng của bạn được miễn phí vận chuyển.'}</p></aside>`; }
function refreshCartTotals() {
 const x=window.scrollX,y=window.scrollY;
 const items=cartItems(),selected=selectedItems();
 const all=main.querySelector('#select-all');
 if(all){all.checked=items.length>0&&selected.length===items.length;all.indeterminate=selected.length>0&&selected.length<items.length;}
 const count=main.querySelector('.cart-toolbar > span');
 if(count)count.textContent=`Đã chọn ${selected.length}/${items.length} tựa sách`;
 main.querySelectorAll('[data-select]').forEach(input=>{input.checked=cart.find(i=>i.bookId===Number(input.dataset.select))?.selected!==false;});
 main.querySelectorAll('[data-quantity]').forEach(input=>{
  const item=items.find(i=>i.bookId===Number(input.dataset.quantity));
  if(item)input.closest('.cart-item').querySelector(':scope > strong').textContent=money(item.book.price*item.quantity);
 });
 const draft=main.querySelector('#coupon')?.value;
 const summaryNode=main.querySelector('.order-summary');
 if(summaryNode)summaryNode.outerHTML=summary();
 if(draft!==undefined&&main.querySelector('#coupon'))main.querySelector('#coupon').value=draft;
 header();
 window.scrollTo({left:x,top:y,behavior:'instant'});
}
function cartPage() { const items=cartItems(); return `<section class="wrap section">${heading('Giỏ sách của bạn',`${items.length} tựa sách đang chờ một ngôi nhà mới.`)}${items.length?`<div class="checkout-layout"><div class="cart-items"><div class="cart-toolbar"><label class="check"><input id="select-all" type="checkbox" ${selectedItems().length===items.length?'checked':''}> Chọn tất cả</label><span>Đã chọn ${selectedItems().length}/${items.length} tựa sách</span></div>${items.map(i=>`<article class="cart-item"><input class="cart-select" type="checkbox" data-select="${i.book.id}" aria-label="Chọn ${esc(i.book.title)} để thanh toán" ${i.selected!==false?'checked':''}><a href="#/sach/${i.book.id}">${cover(i.book,'mini')}</a><div><h3><a href="#/sach/${i.book.id}">${esc(i.book.title)}</a></h3><p>${esc(i.book.author)}</p><b>${money(i.book.price)}</b><button type="button" class="remove" data-remove="${i.book.id}" aria-label="Xóa ${esc(i.book.title)} khỏi giỏ">Xóa khỏi giỏ</button></div><label class="quantity-label">Số lượng<input type="number" min="1" max="${i.book.stock}" value="${i.quantity}" data-quantity="${i.book.id}" aria-label="Số lượng ${esc(i.book.title)}"></label><strong>${money(i.book.price*i.quantity)}</strong></article>`).join('')}<a class="text-link" href="#/sach">← Tiếp tục chọn sách</a></div>${summary()}</div>`:empty('Giỏ hàng chưa có sách','Hãy bắt đầu bằng một cuốn sách khiến bạn tò mò.')}</section>`; }
function field(name,label,type='text',extra='') { return `<label class="field">${label}<input name="${name}" type="${type}" required maxlength="150" ${extra}></label>`; }
function checkoutPage() { if(!user)return empty('Đăng nhập để thanh toán','Giỏ hàng của bạn vẫn được giữ nguyên.','#/dang-nhap','Đăng nhập'); if(!selectedItems().length)return empty('Bạn chưa chọn sách','Chọn những cuốn muốn mua trong giỏ hàng.','#/gio-hang','Về giỏ hàng'); return `<section class="wrap section">${heading('Một bước nữa, sách về tay.','Kiểm tra thông tin để chúng tôi giao sách đến đúng nơi.')}<div class="steps"><span>✓ Giỏ hàng</span><b>02 · Thông tin giao hàng</b><span>03 · Hoàn tất</span></div><div class="checkout-layout"><form id="checkout-form" class="panel"><h2>Thông tin nhận hàng</h2><div class="form-grid">${field('name','Họ và tên','text','autocomplete="name" minlength="2"')}${field('phone','Số điện thoại','tel','autocomplete="tel" pattern="(?:0|\\+84)[0-9]{9}" title="Nhập số điện thoại Việt Nam, ví dụ 0912345678"')}${field('email','Email','email','autocomplete="email"')}${field('city','Tỉnh / Thành phố','text','autocomplete="address-level1"')}</div>${field('address','Địa chỉ đầy đủ (số nhà, đường, phường / xã)','text','autocomplete="street-address" minlength="8"')}<label class="field">Ghi chú giao hàng (không bắt buộc)<textarea name="note" rows="3" maxlength="500" placeholder="Ví dụ: Giao hàng trong giờ hành chính"></textarea></label><h2>Phương thức thanh toán</h2><label class="payment"><input type="radio" name="payment" value="cod" checked> <span><b>Thanh toán khi nhận hàng (COD)</b><small>Thanh toán cho nhân viên giao hàng.</small></span></label>${LIBRA_CONFIG.useMock?'<p class="notice">Đặt hàng thử nghiệm. Không thu tiền và không giao hàng thực tế.</p>':''}<label class="check"><input type="checkbox" required> <span>Tôi đồng ý với <a href="#/chinh-sach" target="_blank">chính sách mua hàng</a>.</span></label><div class="form-error" role="alert"></div><button class="button full" type="submit">Thanh toán · ${money(totals().total)} →</button></form><div>${summary(true)}<div class="panel checkout-books"><h3>Sách trong đơn</h3>${selectedItems().map(i=>`<p><span>${esc(i.book.title)} × ${i.quantity}</span><b>${money(i.book.price*i.quantity)}</b></p>`).join('')}</div></div></div></section>`; }
function authPage(register) { return `<section class="wrap auth-layout"><aside class="auth-intro"><div class="eyebrow">CÙNG LIBRA, ĐỌC NHIỀU HƠN</div><h2>Một tài khoản.<br><em>Vạn trang sách hay.</em></h2><p>Lưu những cuốn sách yêu thích và tiếp tục hành trình đọc của riêng bạn.</p><span>✳</span></aside><div class="auth-form"><a class="muted" href="#/">← Về trang chủ</a><h1>${register?'Tạo tài khoản':'Chào mừng trở lại.'}</h1><p class="muted">${register?'Bắt đầu hành trình cùng Libra.':'Cuốn sách tiếp theo đang chờ bạn.'}</p><form id="auth-form" data-register="${register}">${register?field('name','Họ và tên','text','autocomplete="name" minlength="2"'):''}${field('email','Email','email','autocomplete="email"')}${field('password','Mật khẩu','password',`minlength="8" maxlength="128" autocomplete="${register?'new-password':'current-password'}"`)}${register?field('confirm','Xác nhận mật khẩu','password','minlength="8" autocomplete="new-password"'):''}<label class="check"><input type="checkbox" id="show-password"> Hiện mật khẩu</label><div class="form-error" role="alert"></div><button type="submit" class="button full">${register?'Đăng ký':'Đăng nhập'} →</button></form><p>${register?'Đã có tài khoản? <a href="#/dang-nhap">Đăng nhập</a>':'Chưa có tài khoản? <a href="#/dang-ky">Đăng ký ngay</a>'}</p>${LIBRA_CONFIG.useMock?'<p class="notice">Tài khoản demo: <b>demo@libra.vn</b><br>Mật khẩu: <b>Libra@123</b><br>Nhân viên: <b>staff@libra.vn</b> / <b>Staff@123</b><br>Quản lý: <b>manager@libra.vn</b> / <b>Manager@123</b><br>Quản trị: <b>admin@libra.vn</b> / <b>Admin@123</b><br>Không lưu mật khẩu hoặc xác thực tài khoản thật.</p>':''}</div></section>`; }
async function ordersPage(version,successId) { main.innerHTML=`<section class="wrap section">${heading('Đơn hàng của tôi')}<p role="status">Đang tải đơn hàng…</p></section>`; try { const orders=await LibraAPI.orders(); if(version!==routeVersion)return; main.innerHTML=`<section class="wrap section">${heading(successId?'Cảm ơn bạn đã chọn Libra!':'Đơn hàng của tôi',successId?'Đơn hàng đã được ghi nhận. Bạn có thể xem chi tiết bên dưới.':'Theo dõi những cuốn sách trên hành trình đến với bạn.')}${LIBRA_CONFIG.useMock?'<p class="notice">Lịch sử đơn demo được lưu trên trình duyệt này theo tài khoản đăng nhập. Thông tin nhận hàng không được lưu.</p>':''}${orders.length?orders.map(o=>`<article class="panel order"><div class="order-heading"><div><b>${esc(o.id)}</b><p>${new Date(o.createdAt).toLocaleString('vi-VN')}</p></div><span class="status">${esc(o.status)}</span></div>${o.items.map(i=>`<div class="order-line"><span>${esc(i.title)} <small>× ${i.quantity}</small></span><b>${money(i.price*i.quantity)}</b></div>`).join('')}<div class="order-total"><span>Vận chuyển: ${money(o.shipping)} · Giảm giá: ${money(o.discount)}</span><strong>Tổng: ${money(o.total)}</strong></div></article>`).join(''):empty('Chưa có đơn hàng','Những cuốn sách bạn đặt sẽ xuất hiện tại đây.')}</section>`; } catch(error) { if(version===routeVersion)main.innerHTML=empty('Chưa tải được đơn hàng',esc(error.message),'#/don-hang','Thử lại'); } }
async function render() {
 const version=++routeVersion; const [path,query='']=(location.hash.slice(1)||'/').split('?'),params=new URLSearchParams(query);
 header(); document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(path==='/'?'home':path==='/sach'?'catalog':'')));
 document.querySelector('#search').value=params.get('q')||'';
 if(['/quan-tri','/quan-ly','/nhan-vien'].includes(path)){await renderAdmin(version,path);return;}
 if(path==='/don-hang') { await ordersPage(version,params.get('success')); }
 else if(path==='/')main.innerHTML=home();
 else if(path==='/sach'||path==='/yeu-thich')main.innerHTML=catalog(params,path==='/yeu-thich');
 else if(/^\/sach\/\d+$/.test(path))main.innerHTML=detail(Number(path.split('/')[2]));
 else if(path==='/gio-hang')main.innerHTML=cartPage();
 else if(path==='/thanh-toan')main.innerHTML=checkoutPage();
 else if(path==='/dang-ky'||path==='/dang-nhap'||(path==='/tai-khoan'&&!user))main.innerHTML=authPage(path==='/dang-ky');
 else if(path==='/tai-khoan')main.innerHTML=`<section class="wrap section">${heading(`Xin chào, ${esc(user.name)}.`,esc(user.email))}<div class="panel account-panel"><h2>Góc đọc của bạn</h2><p>Vai trò: ${roleName(user.role)}</p>${user.role!=='customer'?`<a class="button" href="${roleHome(user.role)}">Vào khu vực làm việc →</a>`:''}<a class="button" href="#/don-hang">Xem đơn hàng →</a><a class="button secondary" href="#/yeu-thich">Sách yêu thích ♡</a><button class="text-button" id="logout">Đăng xuất</button></div></section>`;
 else if(path==='/gioi-thieu')main.innerHTML=`<section class="wrap section prose">${heading('Những câu chuyện kết nối chúng ta.')}<p class="lead">Libra là một góc nhỏ dành cho người yêu sách, nơi mỗi lần ghé qua là một cơ hội tìm thấy điều mới mẻ.</p><h2>Chọn sách bằng sự tò mò</h2><p>Từ văn học đến khoa học, từ tuổi thơ đến những bài học trưởng thành — bạn luôn có thể tìm một trang sách để bắt đầu.</p><a class="button" href="#/sach">Khám phá kệ sách →</a></section>`;
 else if(path==='/chinh-sach')main.innerHTML=`<section class="wrap section prose">${heading('Giao hàng & đổi trả')}<p class="notice">Nội dung chính sách minh họa cho bản demo, cần cập nhật trước khi kinh doanh thực tế.</p><h2>Giao hàng</h2><p>Phí giao hàng minh họa là 25.000₫. Đơn hàng từ ${LIBRA_CONFIG.useMock?'299.000':'300.000'}₫ được miễn phí vận chuyển, tính theo giá trị sách trước mã giảm giá.</p><h2>Ưu đãi</h2><p>Mã LIBRA10 giảm 10% giá trị sách, tối đa 50.000₫ mỗi đơn.</p><h2>Đổi trả</h2><p>Chính sách mẫu: hỗ trợ yêu cầu đổi trả trong 7 ngày nếu sách giao sai hoặc lỗi in ấn. Vui lòng giữ sách và bao bì để đối chiếu.</p><h2>Dữ liệu thử nghiệm</h2><p>Giỏ hàng, sách yêu thích và lịch sử đơn demo lưu tại trình duyệt. Chế độ demo không lưu mật khẩu hoặc địa chỉ giao hàng.</p></section>`;
 else main.innerHTML=empty('Trang này chưa có','Quay lại nhà sách để tiếp tục khám phá.','#/','Về trang chủ');
 if(version!==routeVersion)return;
 document.title=(main.querySelector('h1')?.textContent||'Nhà sách của bạn')+' | Libra';
 window.scrollTo(0,0);
}
function updateParams(values) { const [path,query='']=(location.hash.slice(1)||'/sach').split('?');const p=new URLSearchParams(query);Object.entries(values).forEach(([key,value])=>value?p.set(key,value):p.delete(key));location.hash=path+'?'+p.toString(); }
function addBook(id,quantity=1) { const b=books.find(b=>b.id===id); if(!b)return; const existing=cart.find(i=>i.bookId===id); if(!Number.isInteger(quantity)||quantity<1||(existing?.quantity||0)+quantity>b.stock){toast('Số lượng vượt tồn kho hoặc không hợp lệ.');return;} if(existing)existing.quantity+=quantity;else cart.push({bookId:id,quantity});save('cart',cart);header();toast(`Đã thêm “${b.title}” vào giỏ hàng.`); }
document.addEventListener('click',async event=>{
 const target=event.target.closest('button'); if(!target)return;
 if(target.dataset.add)addBook(Number(target.dataset.add),target.dataset.detail?Number(document.querySelector('#quantity').value):1);
 if(target.dataset.favorite){const id=Number(target.dataset.favorite);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save('favorites',favorites);target.textContent=favorites.includes(id)?'♥':'♡';target.classList.toggle('liked',favorites.includes(id));target.setAttribute('aria-pressed',String(favorites.includes(id)));target.setAttribute('aria-label',favorites.includes(id)?'Bỏ yêu thích':'Yêu thích');if(location.hash.startsWith('#/yeu-thich'))render();}
 if(target.dataset.remove){cart=cart.filter(i=>i.bookId!==Number(target.dataset.remove));save('cart',cart);render();toast('Đã xóa sách khỏi giỏ.');}
 if(target.dataset.page)updateParams({page:target.dataset.page});
 if(target.id==='logout'){try{await LibraAPI.logout();user=null;save('user',null);location.hash='/dang-nhap';toast('Bạn đã đăng xuất.');}catch(error){toast(error.message);}}
});
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.dataset.select){const item=cart.find(i=>i.bookId===Number(el.dataset.select));if(item)item.selected=el.checked;save('cart',cart);refreshCartTotals();return;}
 if(el.id==='select-all'){cart.forEach(i=>i.selected=el.checked);save('cart',cart);refreshCartTotals();return;}
 if(el.id==='sort')updateParams({sort:el.value,page:''});
 if(el.id==='show-password')main.querySelectorAll('input[name="password"],input[name="confirm"]').forEach(i=>i.type=el.checked?'text':'password');
 if(el.dataset.quantity){const i=cart.find(i=>i.bookId===Number(el.dataset.quantity)),b=books.find(b=>b.id===i.bookId),n=Number(el.value);if(!Number.isInteger(n)||n<1||n>b.stock){el.value=i.quantity;toast(`Chọn từ 1 đến ${b.stock} cuốn.`);return;}i.quantity=n;save('cart',cart);refreshCartTotals();}
});
document.addEventListener('submit',async event=>{
 const form=event.target;event.preventDefault();
 if(form.id==='search-form'){location.hash='/sach?q='+encodeURIComponent(document.querySelector('#search').value.trim());return;}
 if(form.id==='filter-form'){const f=new FormData(form);updateParams({category:f.get('category'),max:f.get('max')==='0'?'':f.get('max'),stock:f.has('stock')?'1':'',sale:f.has('sale')?'1':'',page:''});return;}
 if(form.id==='coupon-form'){const value=document.querySelector('#coupon').value.trim().toUpperCase();if(value&&value!=='LIBRA10'){toast('Mã không hợp lệ. Thử mã LIBRA10.');return;}coupon=value;render();toast(value?'Đã áp dụng mã giảm giá.':'Đã bỏ mã giảm giá.');return;}
 if(!['auth-form','checkout-form'].includes(form.id))return;
 const button=form.querySelector('button[type="submit"]'),errorBox=form.querySelector('.form-error');errorBox.textContent=''; const data=Object.fromEntries(new FormData(form));
 if(Object.entries(data).some(([k,v])=>!['note','payment'].includes(k)&&!String(v).trim())){errorBox.textContent='Vui lòng điền đầy đủ thông tin, không chỉ nhập khoảng trắng.';return;}
 if(form.dataset.register==='true'&&data.password!==data.confirm){errorBox.textContent='Mật khẩu xác nhận chưa khớp.';return;}
 button.disabled=true;const original=button.textContent;button.textContent='Đang xử lý…';
 try {
  if(form.id==='auth-form'){user=await LibraAPI[form.dataset.register==='true'?'register':'login']({name:data.name?.trim(),email:data.email.trim(),password:data.password});save('user',user);const destination=roleHome(user.role);if(location.hash===destination)render();else location.hash=destination;toast(LIBRA_CONFIG.useMock?'Đã vào tài khoản demo.':'Thành công.');}
  else {const purchased=selectedItems().map(i=>({bookId:i.bookId,quantity:i.quantity}));if(!purchased.length)throw new Error('Vui lòng chọn sách trước khi thanh toán.');const order=await LibraAPI.createOrder({customer:{name:data.name.trim(),phone:data.phone,email:data.email,city:data.city.trim(),address:data.address.trim()},note:data.note,items:purchased,coupon,paymentMethod:data.payment});cart=cart.filter(i=>!purchased.some(p=>p.bookId===i.bookId));coupon='';save('cart',cart);location.hash='/don-hang?success='+encodeURIComponent(order.id);}
 }catch(error){errorBox.textContent=error.message;}finally{button.disabled=false;button.textContent=original;}
});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
window.addEventListener('hashchange',()=>{if(loaded)render();});
async function init(){if(!LIBRA_CONFIG.useMock)return liveInit();main.innerHTML='<div class="empty" role="status">Đang mở kệ sách…</div>';try{user=await LibraAPI.me().catch(()=>null);save('user',user);books=await LibraAPI.books();if(!Array.isArray(books))throw new Error('API sách phải trả về một mảng.');cart=cart.filter(i=>books.some(b=>b.id===i.bookId&&b.stock>0)&&Number.isInteger(i.quantity)&&i.quantity>0).map(i=>({...i,quantity:Math.min(i.quantity,books.find(b=>b.id===i.bookId).stock)}));save('cart',cart);loaded=true;await render();}catch(error){main.innerHTML=`<div class="empty"><h1>Chưa thể tải nhà sách</h1><p>${esc(error.message)}</p><button class="button" id="retry">Thử lại</button></div>`;document.querySelector('#retry').onclick=init;}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();






document.addEventListener('error',event=>{const img=event.target;if(img.tagName!=='IMG'||!img.closest('.real-cover'))return;const box=img.closest('.real-cover');box.classList.add('cover-unavailable');const title=document.createElement('strong');title.textContent=img.alt;const note=document.createElement('small');note.textContent='Ảnh bìa tạm thời chưa tải được';box.replaceChildren(title,note);},true);
